    # Defensive defaults
    x = observation.get("player", {}).get("pos", [0, 0])
    if not isinstance(x, (list, tuple)) or len(x) < 2:
        x = [0, 0]
    px, py = x[0], x[1]

    # Heuristic: try to move towards a potential resource/goal while avoiding edges.
    # Use available hints from observation defensively.
    grid = observation.get("grid", [])
    height = len(grid) if isinstance(grid, list) else 0
    width = len(grid[0]) if height > 0 and isinstance(grid[0], list) else 0

    # Simple local goal: look for a nearby positive signal in the 3x3 neighborhood.
    best_dx, best_dy = 0, 0
    best_score = -float("inf")

    for dy in (-1, 0, 1):
        for dx in (-1, 0, 1):
            if dx == 0 and dy == 0:
                continue
            nx, ny = px + dx, py + dy
            if width > 0 and height > 0:
                if nx < 0 or ny < 0 or nx >= width or ny >= height:
                    continue
                cell = grid[ny][nx]
            else:
                cell = observation.get("cell", None)

            # Score hints: prefer resources ('R'), threaten evaders ('E' considered bad), open space.
            score = 0
            if isinstance(cell, str):
                if "R" in cell:
                    score += 2
                if "P" in cell or "E" in cell:
                    score -= 1
            elif isinstance(cell, dict):
                if cell.get("resource") is True:
                    score += 2
                if cell.get("enemy") is True:
                    score -= 1
            else:
                # if unknown, small bias to stay near center
                score += 0.1

            if score > best_score:
                best_score = score
                best_dx, best_dy = dx, dy

    # If no better move found, revert to simple stay or default towards center when possible
    if best_dx == 0 and best_dy == 0:
        # Try to move towards center of observed area if available
        if width > 0 and height > 0:
            center_dx = 0
            center_dy = 0
            if px > width // 2:
                center_dx = -1
            elif px < width // 2:
                center_dx = 1
            if py > height // 2:
                center_dy = -1
            elif py < height // 2:
                center_dy = 1
            if center_dx != 0 or center_dy != 0:
                best_dx, best_dy = center_dx, center_dy

    # Clamp to allowed values
    if best_dx not in (-1, 0, 1):
        best_dx = 0
    if best_dy not in (-1, 0, 1):
        best_dy = 0

    return [best_dx, best_dy]

